import { unified } from "unified";
import rehypeParse from "rehype-parse";
import rehypeSanitize from "rehype-sanitize";
import rehypeStringify from "rehype-stringify";
import type { Root, Element } from "hast";
import { toEditorHTML } from "./post-content";
// Restrict inline style values to formatting generated by the toolbar.
const style =
  /^(?:(?:color:\s*(?:#[0-9a-fA-F]{3,8}|rgb\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}\s*\))|font-size:\s*(?:12|14|16|18|20|24|28|32)px|text-align:\s*(?:left|center|right|justify));?\s*)+$/;
const https = /^https:\/\//i;
const frame =
  /^https:\/\/(?:www\.youtube-nocookie\.com\/embed\/[\w-]{11}|player\.vimeo\.com\/video\/\d+)$/;
const processor = unified()
  .use(rehypeParse, { fragment: true })
  .use(rehypeSanitize, {
    tagNames: [
      "p",
      "br",
      "strong",
      "b",
      "em",
      "i",
      "u",
      "s",
      "strike",
      "h2",
      "h3",
      "ul",
      "ol",
      "li",
      "blockquote",
      "a",
      "span",
      "img",
      "figure",
      "figcaption",
      "iframe",
      "video",
      "hr",
      "code",
      "pre",
    ],
    attributes: {
      "*": [["style", style]],
      a: [["href", /^https:\/\//i, /^mailto:/i, /^tel:/i], "title"],
      img: [
        ["src", https],
        "alt",
        "title",
        ["width", /^(?:[1-9]\d{0,2}|1[0-5]\d{2}|1600)$/],
        ["height", /^[1-9]\d{0,3}$/],
      ],
      figure: [
        ["dataVideoUrl", https],
        ["className", "article-video"],
      ],
      iframe: [["src", frame], "title"],
      video: [
        ["src", https],
        ["poster", https],
      ],
      ol: ["start"],
    },
    protocols: {
      href: ["https", "mailto", "tel"],
      src: ["https"],
      poster: ["https"],
      dataVideoUrl: ["https"],
    },
    required: {
      a: { target: "_blank", rel: ["noopener", "noreferrer"] },
      img: { loading: "lazy" },
      iframe: {
        loading: "lazy",
        allowFullScreen: true,
        referrerPolicy: "strict-origin-when-cross-origin",
        sandbox: ["allow-scripts", "allow-same-origin", "allow-presentation"],
      },
      video: { controls: true, playsInline: true, preload: "metadata" },
    },
    strip: [
      "script",
      "style",
      "object",
      "embed",
      "svg",
      "math",
      "form",
      "input",
      "button",
      "textarea",
      "select",
      "template",
    ],
  })
  .use(function removeUnusableMedia() {
    return (tree: Root) => {
      function clean(parent: Root | Element) {
        for (let i = parent.children.length - 1; i >= 0; i--) {
          const child = parent.children[i];
          if (child.type !== "element") continue;
          if (
            ["img", "iframe", "video"].includes(child.tagName) &&
            !child.properties.src
          )
            parent.children.splice(i, 1);
          else clean(child);
        }
      }
      clean(tree);
    };
  })
  .use(rehypeStringify);
export function sanitizePostHTML(html: string): string {
  return String(processor.processSync(html));
}
export function renderPostBody(body: string, format?: "text" | "html") {
  return sanitizePostHTML(toEditorHTML(body, format));
}
